// Settings of the example website "Sutra Sample Shop" (SutraFlow sample: Chat for customers and support).
// Do not edit this file: put your values in config.local.php (copy config.local.example.php), or in environment
// variables of the web server. An environment variable wins over config.local.php, which wins over the defaults here.

$localFile = __DIR__ . '/config.local.php';
$local = is_file($localFile) ? (require $localFile) : [];
if (!is_array($local)) $local = [];

function shop_setting(string $name, $default)
{
    global $local;
    $env = getenv($name);
    if ($env !== false && $env !== '') return $env;
    return array_key_exists($name, $local) && $local[$name] !== '' ? $local[$name] : $default;
}

// Where SutraFlow's gateway answers, as the visitor's browser reaches it: this computer (http://127.0.0.1:8080)
// or a SutraFlow on another server (https://sutra.example.com). The chat button and the chat come from there.
define('SUTRAFLOW_URL', rtrim((string)shop_setting('SUTRAFLOW_URL', 'http://127.0.0.1:8080'), '/'));
// The agent name of "Sample: Customer and support chat".
define('CHAT_AGENT', (string)shop_setting('CHAT_AGENT', 'shop-help'));
// The secret this website signs chat tokens with: the same text as the Secret property CHAT_SITE_SECRET of the
// SutraFlow project. A long random text, at least 32 characters. Never put it in version control.
define('CHAT_SECRET', (string)shop_setting('CHAT_SECRET', ''));
// Must match the policy "Sample chat website sign-in": issuer, audience and the life of a token.
define('CHAT_ISSUER', (string)shop_setting('CHAT_ISSUER', 'sutra-sample-shop'));
define('CHAT_AUDIENCE', (string)shop_setting('CHAT_AUDIENCE', 'shop-help'));
define('CHAT_TOKEN_MINUTES', max(1, min(60, (int)shop_setting('CHAT_TOKEN_MINUTES', 15))));
define('SHOP_NAME', (string)shop_setting('SHOP_NAME', 'Sutra Sample Shop'));

/** True when the secret is set and long enough to sign tokens. */
function chat_ready(): bool { return strlen(CHAT_SECRET) >= 32; }

// Demo accounts. A real website signs people in its own way (its database, single sign-on); what matters
// for SutraFlow is only the token it issues afterwards: who (sub, name) and what they may do (role).
const USERS = [
    'asha' => ['password' => 'asha-demo', 'sub' => 'C-7', 'name' => 'Asha', 'role' => 'customer'],
    'ravi' => ['password' => 'ravi-demo', 'sub' => 'S-1', 'name' => 'Ravi', 'role' => 'support'],
];
